const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '比例尺 1:10000' },
      { kind: 'text', payload: '图上距离 7 厘米' },
      { kind: 'text', payload: '实际距离 70000 厘米' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '7 厘米' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var fs = Math.max(12, Math.min(20, Math.round(H * 0.045)));
    var y = Math.round(H * 0.55);
    var margin = Math.max(44, Math.round(W * 0.12));
    var x0 = margin;
    var x1 = W - margin;
    var step = (x1 - x0) / 7;
    var tickH = Math.max(7, Math.round(H * 0.028));
    var majorH = tickH * 2;
    var paths = [];
    paths.push({ id: 'baseline', commands: visualSdk.polyline([[x0, y], [x1, y]]) });
    for (var i = 0; i <= 7; i++) {
      var x = x0 + step * i;
      var h = (i === 0 || i === 7) ? majorH : tickH;
      paths.push({ id: 'tick' + i, commands: visualSdk.polyline([[x, y - h], [x, y + h]]) });
    }
    function measure(idx, text) {
      var m = metrics && metrics[idx];
      if (m && typeof m.width === 'number') return m.width;
      if (m && typeof m.w === 'number') return m.w;
      return Math.max(fs, text.length * fs * 0.8);
    }
    var labels = [
      '比例尺 1:10000',
      '图上距离 7 厘米',
      '实际距离 70000 厘米',
      '0',
      '7 厘米'
    ];
    var scaleY = Math.max(22, y - majorH - 58);
    var mapY = Math.max(46, y - majorH - 22);
    var tickLabelY = Math.min(H - 44, y + majorH + 24);
    var actualY = Math.min(H - 16, y + majorH + 62);
    var wMap = measure(1, labels[1]);
    var wActual = measure(2, labels[2]);
    var w0 = measure(3, labels[3]);
    var w7 = measure(4, labels[4]);
    var root = { type: 'group', children: [] };
    for (var p = 0; p < paths.length; p++) {
      root.children.push({ type: 'path', pathId: paths[p].id, stroke: '#26354a', strokeWidth: paths[p].id === 'baseline' ? 2 : 1.5 });
    }
    root.children.push({ type: 'label', x: margin, y: scaleY, text: labels[0], fontSize: fs, fill: '#26354a' });
    root.children.push({ type: 'label', x: W / 2 - wMap / 2, y: mapY, text: labels[1], fontSize: fs, fill: '#26354a' });
    root.children.push({ type: 'label', x: W / 2 - wActual / 2, y: actualY, text: labels[2], fontSize: fs, fill: '#26354a' });
    root.children.push({ type: 'label', x: x0 - w0 / 2, y: tickLabelY, text: labels[3], fontSize: fs, fill: '#26354a' });
    root.children.push({ type: 'label', x: x1 - w7 / 2, y: tickLabelY, text: labels[4], fontSize: fs, fill: '#26354a' });
    return {
      schemaVersion: 1,
      sceneId: 'scale-line-7cm',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: root
    };
  }
};
